pub async fn file_hold_recovery_assess_retained(root: String, slot_key: String, report: Rc<DurableHoldHolderReport>, released_by: NonEmptyStr, retention: Rc<CasSlotRetention>, filesystem: &Filesystem) -> std::result::Result<Rc<FileHoldRecoveryAssessment>, std::boxed::Box<dyn std::error::Error>> {
    Ok(match (*crate::std_durable_exclusive_hold::durable_hold_recovery_assess(observe_file_hold_retained(root.clone(), slot_key.clone(), retention.clone(), filesystem).await?, report)).clone() {
    DurableHoldRecoveryAssessment::HoldRecoveryRefused { refusal: r, .. } => Rc::new(FileHoldRecoveryAssessment::FileHoldRecoveryNotEligible {
    slot_key: slot_key.clone(),
    refusal: r.clone(),
}),
    DurableHoldRecoveryAssessment::HoldRecoveryEligible { generation: g, dead_holder: h, evidence: e, .. } => Rc::new(FileHoldRecoveryAssessment::FileHoldRecoveryPlanned {
    plan: Rc::new(FileHoldReleasePlan {
    root: root.clone(),
    slot_key: slot_key.clone(),
    owner: h.clone(),
    generation: g.clone(),
    free_payload: hold_slot_payload(Rc::new(DurableHoldState::DurableHoldFree {
    released_by: released_by.clone(),
})),
    retention: retention.clone(),
}),
    dead_holder: h.clone(),
    evidence: e.clone(),
}),
})
}

pub async fn file_hold_recovery_assess(root: String, slot_key: String, report: Rc<DurableHoldHolderReport>, released_by: NonEmptyStr, filesystem: &Filesystem) -> std::result::Result<Rc<FileHoldRecoveryAssessment>, std::boxed::Box<dyn std::error::Error>> {
    Ok(file_hold_recovery_assess_retained(root, slot_key, report, released_by, Rc::new(CasSlotRetention::KeepAllGenerations), filesystem).await?)
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(tag = "_variant")]
pub enum FileHoldDeadHolderRecovery {
    FileHoldDeadHolderRecovered {
        dead_holder: DurableHoldOwnerRef,
        evidence: NonEmptyStr,
    },
    FileHoldDeadHolderHolderLive {
        holder: DurableHoldOwnerRef,
        evidence: NonEmptyStr,
    },
    FileHoldDeadHolderHolderUnobservable {
        holder: DurableHoldOwnerRef,
        cause: NonEmptyStr,
    },
    FileHoldDeadHolderNotEligible {
        refusal: Rc<DurableHoldRecoveryRefusal>,
    },
    FileHoldDeadHolderReleaseLost,
    FileHoldDeadHolderReleaseStoreUnavailable {
        cause: Rc<CasStoreFailure>,
    },
    FileHoldDeadHolderReleaseKeyNotAddressable,
}

pub async fn file_hold_recover_dead_holder(root: String, slot_key: String, holder: NonEmptyStr, generation: i64, released_by: NonEmptyStr, live_owner: impl Fn(NonEmptyStr) -> Rc<DurableHoldHolderLiveness> + Clone, filesystem: &Filesystem) -> std::result::Result<Rc<FileHoldDeadHolderRecovery>, std::boxed::Box<dyn std::error::Error>> {
    Ok(match (*live_owner(holder.clone())).clone() {
    DurableHoldHolderLiveness::HolderObservedDead { evidence: e, .. } => match (*file_hold_recovery_assess(root, slot_key, Rc::new(DurableHoldHolderReport {
    holder: holder.clone(),
    generation: generation.clone(),
    liveness: Rc::new(DurableHoldHolderLiveness::HolderObservedDead {
    evidence: e.clone(),
}),
}), released_by, filesystem).await?).clone() {
    FileHoldRecoveryAssessment::FileHoldRecoveryPlanned { plan: p, dead_holder: d, evidence: ev, .. } => match (*file_hold_release_commit(p.clone(), filesystem).await?).clone() {
    FileHoldReleaseOutcome::FileHoldReleased { .. } => Rc::new(FileHoldDeadHolderRecovery::FileHoldDeadHolderRecovered {
    dead_holder: d.clone(),
    evidence: ev.clone(),
}),
    FileHoldReleaseOutcome::FileHoldReleaseLost { slot_key: _, .. } => Rc::new(FileHoldDeadHolderRecovery::FileHoldDeadHolderReleaseLost),
    FileHoldReleaseOutcome::FileHoldReleaseStoreUnavailable { cause: c, .. } => Rc::new(FileHoldDeadHolderRecovery::FileHoldDeadHolderReleaseStoreUnavailable {
    cause: c.clone(),
}),
    FileHoldReleaseOutcome::FileHoldReleaseKeyNotSlotAddressable { slot_key: _, .. } => Rc::new(FileHoldDeadHolderRecovery::FileHoldDeadHolderReleaseKeyNotAddressable),
},
    FileHoldRecoveryAssessment::FileHoldRecoveryNotEligible { refusal: r, .. } => Rc::new(FileHoldDeadHolderRecovery::FileHoldDeadHolderNotEligible {
    refusal: r.clone(),
}),
},
    DurableHoldHolderLiveness::HolderObservedLive { evidence: e, .. } => Rc::new(FileHoldDeadHolderRecovery::FileHoldDeadHolderHolderLive {
    holder: holder.clone(),
    evidence: e.clone(),
}),
    DurableHoldHolderLiveness::HolderLivenessUnobservable { cause: c, .. } => Rc::new(FileHoldDeadHolderRecovery::FileHoldDeadHolderHolderUnobservable {
    holder: holder.clone(),
    cause: c.clone(),
}),
})
}

